import requests


def detect_transport_utilities(port=None, transport_type=None):
    """
    Generate transport type and port if not specified.

    :param Optional[int] port: Port to communication
    :param Optional[str] transport_type: https or http
    :return tuple[str, int]: (transport_type, port)
    """
    if transport_type is None:
        transport_type = "https" if port == 443 else "http"
    assert transport_type in ["http", "https"]
    if port is None:
        port = 443 if transport_type == "https" else 80
    return transport_type, port


class Client:

    def __init__(self, hostname, port=None, transport_type=None, *args, **kwargs):
        """
        Establish connection over http or https transport.

        :param str hostname: Domain name of the URL
        :param int port: Port to communication
        :param str transport_type: Http or Https
        """
        self.hostname = hostname
        self.transport_type, self.port = detect_transport_utilities(port, transport_type)

    def _generate_url(self):
        return f"{self.transport_type}://{self.hostname}:{self.port}"

    @staticmethod
    def _post_to_server(url, json={}, headers=None, auth=None, timeout=None):
        response = requests.post(url, json=json, auth=auth, headers=headers, timeout=timeout)
        response.raise_for_status()  # Raises HTTPError, if one occurred
        return response.json()

    @staticmethod
    def _get_from_server(url, params=None, auth=None, cert=None, headers=None, timeout=None):
        response = requests.get(url, params=params, auth=auth, cert=cert, headers=headers, timeout=timeout)
        response.raise_for_status()  # Raises HTTPError, if one occurred
        return response.json() if response.headers['content-type'] == 'application/json' else response

    @staticmethod
    def _delete_from_server(url, json=None, auth=None, headers=None, timeout=None):
        response = requests.delete(url, json=json, auth=auth, headers=headers, timeout=timeout)
        response.raise_for_status()  # Raises HTTPError, if one occurred
        return response.json() is None
